challenges.solution:
from collections import Counter

def count_status_codes(log_text):
    counts = Counter()
    for line in log_text.splitlines():
        parts = line.split('"')
        if len(parts) < 3:
            continue
        fields = parts[2].split()
        if fields and fields[0].isdigit():
            counts[int(fields[0])] += 1
    return dict(counts)

