import json

def storage_findings(json_text):
    report = {}
    for account in json.loads(json_text):
        findings = []
        if account.get('allowBlobPublicAccess') is True:
            findings.append('public blob access')
        if account.get('minimumTlsVersion') in ('TLS1_0', 'TLS1_1'):
            findings.append('old TLS')
        if account.get('enableHttpsTrafficOnly') is False:
            findings.append('HTTP allowed')
        if findings:
            report[account['name']] = findings
    return report

