def changed_paths(old, new, prefix=''):
    paths = []
    for key in old.keys() | new.keys():
        path = f'{prefix}{key}'
        a, b = old.get(key, None), new.get(key, None)
        if isinstance(a, dict) and isinstance(b, dict):
            paths.extend(changed_paths(a, b, path + '.'))
        elif key not in old or key not in new or a != b:
            paths.append(path)
    return sorted(paths)

def parse_env(text):
    result = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('export '):
            line = line[len('export '):]
        key, _, value = line.partition('=')
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in '"\'':
            value = value[1:-1]
        result[key.strip()] = value
    return result

def latest_version(versions):
    if not versions:
        return None
    return max(versions, key=lambda version: tuple(int(part) for part in version.lstrip('v').split('.')))

