class FakeSleep:
    """Stands in for time.sleep so the tests do not actually wait."""
    def __init__(self):
        self.delays = []
    def __call__(self, seconds):
        self.delays.append(seconds)

def flaky(failures, error=ConnectionError):
    """A function that fails `failures` times, then returns "ok"."""
    state = {"calls": 0}
    def call():
        state["calls"] += 1
        if state["calls"] <= failures:
            raise error(f"attempt {state['calls']} failed")
        return "ok"
    return call

def run_retry(failures, attempts, error=ConnectionError):
    sleep = FakeSleep()
    try:
        result = retry(flaky(failures, error), attempts=attempts, base_delay=0.5, sleep=sleep)
    except Exception as exc:
        result = type(exc).__name__
    return {"result": result, "delays": sleep.delays}

challenges.solution:
import time

def retry(func, attempts=3, base_delay=1.0, sleep=time.sleep):
    for attempt in range(attempts):
        try:
            return func()
        except (ConnectionError, TimeoutError):
            if attempt == attempts - 1:
                raise
            sleep(base_delay * 2 ** attempt)

def unhealthy_pods(text):
    result = {}
    for line in text.splitlines()[1:]:
        fields = line.split()
        if len(fields) < 3:
            continue
        name, ready, status = fields[:3]
        have, want = ready.split('/')
        if have != want and status != 'Completed':
            result[name] = status
    return result

